{"file_path":"src/utils/migrations.ts","content":"import type { Task } from '../types';

export const SCHEMA_VERSION = 1;

export interface Persisted {
  version: number;
  tasks: Task[];
}

type Migration = (input: unknown) => Persisted;

// Anything written before versioning existed: a bare Task[] at the tasks key.
const fromUnversioned: Migration = (input) => ({
  version: 1,
  tasks: Array.isArray(input) ? (input as Task[]) : [],
});

const MIGRATIONS: Record<number, Migration> = {
  0: fromUnversioned,
};

export function migrate(raw: unknown): Persisted {
  if (raw && typeof raw === 'object' && 'version' in raw) {
    const candidate = raw as Persisted;
    if (candidate.version === SCHEMA_VERSION) return candidate;
    const step = MIGRATIONS[candidate.version];
    return step ? migrate(step(candidate)) : { version: SCHEMA_VERSION, tasks: [] };
  }
  return fromUnversioned(raw);
}
"}

